export const ALL_INDIAN_STATES = Object.keys(INDIAN_STATES_AND_DISTRICTS);

export function getAllStates(): string[] {
  return ALL_INDIAN_STATES;
}

export function findMatchingState(searchStr: string): string | null {
  if (!searchStr) return null;
  const q = searchStr.trim().toLowerCase();
  const exact = ALL_INDIAN_STATES.find((s) => s.toLowerCase() === q);
  if (exact) return exact;
  const partial = ALL_INDIAN_STATES.find((s) => s.toLowerCase().includes(q) || q.includes(s.toLowerCase()));
  return partial || null;
}

export function getDistrictsForState(stateName: string): string[] {
  if (!stateName || stateName === "All States") {
    // Return all districts across India flattened or unique list
    const all = Object.values(INDIAN_STATES_AND_DISTRICTS).flat();
    return Array.from(new Set(all)).sort();
  }

  // Find exact or case-insensitive match
  const match = Object.keys(INDIAN_STATES_AND_DISTRICTS).find(
    (s) => s.toLowerCase() === stateName.trim().toLowerCase()
  );

  return match ? INDIAN_STATES_AND_DISTRICTS[match] : [];
}
